using System.Threading.Tasks;
using Xunit;
using Demo.Pedidos;

namespace Demo.Pedidos.Tests
{
    public class PedidoServiceTests
    {
        [Fact]
        public async Task CreatePedidoWithClienteAndTotal()
        {
            var service = new PedidoService();
            var pedido = await service.CreateAsync("ACME", 150m);
            Assert.Equal("ACME", pedido.Cliente);
            Assert.Equal(150m, pedido.Total);
        }

        [Fact]
        public async Task SignalrBroadcastsPedidoCreatedEvent()
        {
            var service = new PedidoService();
            var pedido = await service.CreateAsync("ACME", 150m);
            Assert.Equal("ACME", pedido.Cliente);
        }
    }
}

