using System;
using System.Threading.Tasks;
namespace Demo.Pedidos
{
    public class Pedido
    {
        public string Cliente { get; set; } = "";
        public decimal Total { get; set; }
    }

    public class PedidoService
    {
        public Task<Pedido> CreateAsync(string cliente, decimal total)
        {
            if (string.IsNullOrWhiteSpace(cliente))
                throw new ArgumentException("Cliente es requerido", nameof(cliente));
            if (total <= 0)
                throw new ArgumentException("Total debe ser mayor a cero", nameof(total));
            var pedido = new Pedido { Cliente = cliente, Total = total };
            return Task.FromResult(pedido);
        }
    }
}

