import { test, expect } from '@playwright/test';

test('ListadoShowsDot', async ({ page }) => {
  await page.goto('/pedidos');
  await expect(page.getByTestId('dot-vencido').first()).toBeVisible();
});

test('ListadoFilterReducesRows', async ({ page }) => {
  await page.goto('/pedidos');
  await page.getByTestId('filtro-cliente').fill('ACME');
  await expect(page.getByTestId('fila-pedido')).toHaveCount(1);
});

test('ListadoInfoOpensInstrucciones', async ({ page }) => {
  await page.goto('/pedidos');
  await page.getByTestId('info-1').click();
  await expect(page.getByTestId('instrucciones')).toBeVisible();
});
